mapper.select:
SELECT


, COALESCE(sys_order.user_name, u.nickname) AS user_name
, COALESCE(sys_order.mobile, u.mobile) AS mobile
FROM sys_order
LEFT JOIN sys_user u ON u.id = sys_order.user_id


    AND sys_order.is_deleted = 0

        AND order_no LIKE CONCAT('%', #{query.orderNo}, '%')


        AND order_type = #{query.orderType}


        AND user_id = #{query.userId}



        AND COALESCE(sys_order.user_name, u.nickname) LIKE CONCAT('%', #{query.userName}, '%')


        AND COALESCE(sys_order.mobile, u.mobile) LIKE CONCAT('%', #{query.mobile}, '%')



        AND biz_id = #{query.bizId}


        AND biz_type = #{query.bizType}



        AND sys_order.status = #{query.status}




        AND sys_order.status IN (1, 2)



        AND pay_type = #{query.payType}



        AND pay_time >= #{query.beginTime}


        AND pay_time <= #{query.endTime}



        AND sys_order.id IN

            #{id}



ORDER BY sys_order.create_time DESC
